function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
function safeText(value){return String(value||'Request failed').split(/\r?\n/,1)[0].replace(/[A-Za-z]:\\[^\s\"']+/g,'<internal-path>').replace(/(^|\s)\/(?:[^\/\s]+\/)+[^\s\"']+/g,'$1<internal-path>').replace(/\b[a-fA-F0-9]{40,64}\b/g,'<internal-id>').slice(0,500)}
function safeDetails(value){const source=value&&typeof value==='object'?value:{},out={},allowed=['requested_start','requested_end','first_session','last_session','session_count','eligible_symbol_dates','complete_symbol_dates','coverage','missing_fields','candidate_symbol_count','listed_date_available','delisted_date_available'];for(const key of allowed){const item=source[key];if(item===undefined)continue;if(Array.isArray(item))out[key]=item.slice(0,20).map(entry=>safeText(entry));else if(item===null||['number','boolean'].includes(typeof item))out[key]=item;else if(typeof item==='string')out[key]=safeText(item)}return out}
