async function submit(input){if(input.confirm_python_execution!==true)throw new Error('Backtest requires explicit Python execution confirmation');const projectId=String(input.project_id||'').trim();if(!projectId||!input.start_date||!input.end_date)throw new Error('project_id, start_date, and end_date are required for run');const job=await call('/api/backtests/jobs',{method:'POST',body:JSON.stringify({project_id:projectId,start_date:String(input.start_date),end_date:String(input.end_date),profile:'runtime',confirm_python_execution:true})});return{status:job.status,job_id:job.id}}
